let dbCalls = 0;
function db(/* query */) { dbCalls++; return {}; }

// Query.posts resolver: one DB call returns N post objects
function resolvePosts(N) {
  db('SELECT * FROM posts LIMIT ' + N);
  const posts = [];
  for (let i = 0; i < N; i++) posts.push({ id: i, author_id: i });
  return posts;
}

// Post.author resolver: fires once PER parent post, isolated, no batching
function resolveAuthor(/* post */) {
  db('SELECT * FROM users WHERE id = ?');
  return {};
}

const N = 50;
const posts = resolvePosts(N);
for (const post of posts) resolveAuthor(post);

console.log('DB calls for N=' + N + ': ' + dbCalls + ' (1 + ' + N + ')');
